package main

// This file is the CANDIDATE SLOT for evolved routing algorithms. During
// optimization, the entire file is replaced (via go build -overlay) with a
// generated implementation. The contract is a single constructor:
//
//	newCandidateRouter(view, source, localBalances, spec)
//
// returning a routing.SimRouter. The router sees only the public gossip
// graph, its own channel balances and per-attempt feedback — the same
// information a real Lightning sender has. The in-tree implementation below
// is the seed algorithm: a deliberately simple fee-optimizing Dijkstra with
// failure blacklisting and halving-based MPP splitting.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

// candidateEdge is one directed edge of the public graph: a channel from
// one node to another, with the policy the sending node announced.
type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

// fee returns the fee the sending node charges to forward amt over this
// edge.
func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

// usable reports whether the edge can carry the given amount per its
// announced policy.
func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	// The public capacity is a hard upper bound on what can flow.
	return amt <= e.capacity
}

// candidateRouter is the seed algorithm: cheapest-path routing with a
// failure blacklist and amount halving when no route is found.
type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// incomingEdges maps a node to the directed edges arriving at it,
	// the natural shape for backward Dijkstra.
	incomingEdges map[route.Vertex][]*candidateEdge

	// localBalances is the exact outbound liquidity of our own channels.
	localBalances map[uint64]lnwire.MilliSatoshi

	// failedAmt records, per directed channel, the lowest amount that
	// failed with a liquidity error; routes are built to stay below it.
	failedAmt map[uint64]lnwire.MilliSatoshi

	// shardAmt is the current shard size for MPP splitting.
	shardAmt lnwire.MilliSatoshi

	// partsUsed counts the successful shards so far.
	partsUsed uint32

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route
}

// newCandidateRouter builds the router for one payment. This signature is
// the stable contract between the harness and generated candidates.
func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		failedAmt:     make(map[uint64]lnwire.MilliSatoshi),
		shardAmt:      spec.Amount,
		pending:       make(map[uint64]*route.Route),
	}

	// Build the adjacency list from gossip. Iterating a node's channels
	// yields, per channel, the policy the OTHER node announced toward us
	// (InPolicy). That is exactly the policy governing the directed edge
	// other -> node, so we record the reversed edge at each visit.
	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				router.incomingEdges[edge.to] = append(
					router.incomingEdges[edge.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

// dijkstraItem is a priority queue entry.
type dijkstraItem struct {
	node route.Vertex
	cost lnwire.MilliSatoshi
	idx  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int           { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool { return q[i].cost < q[j].cost }
func (q dijkstraQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// findRoute computes the cheapest usable path delivering amt to the target,
// walking backward from the target so fees accumulate correctly.
func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (*route.Route,
	error) {

	// dist[node] = amount that must arrive at node to deliver amt.
	dist := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = amt
	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{node: r.spec.Target, cost: amt})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node, arriving := item.node, item.cost

		if arriving > dist[node] {
			continue
		}
		if node == r.source {
			break
		}

		// Consider all edges INTO node: for edge u->node, u must
		// send arriving plus u's fee.
		for _, edge := range r.incomingEdges[node] {
			amtOver := arriving

			if !edge.usable(amtOver) {
				continue
			}

			// Skip channels whose liquidity failure bound says
			// this amount cannot pass.
			if bound, ok := r.failedAmt[edge.chanID]; ok &&
				amtOver >= bound {

				continue
			}

			// Our own channels: check exact local balance.
			if edge.from == r.source {
				if r.localBalances[edge.chanID] < amtOver {
					continue
				}
			}

			var sending lnwire.MilliSatoshi
			if edge.from == r.source {
				// We pay no fee to ourselves.
				sending = amtOver
			} else {
				sending = amtOver + edge.fee(amtOver)
			}

			best, ok := dist[edge.from]
			if !ok || sending < best {
				dist[edge.from] = sending
				next[edge.from] = edge
				heap.Push(pq, &dijkstraItem{
					node: edge.from,
					cost: sending,
				})
			}
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

// buildRoute walks the next-pointers from source to target and constructs a
// route with correctly accumulated fees and cltv deltas.
func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = 40

	// Collect the path edges source -> target.
	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	// Amounts and expiries per channel, computed backward.
	numHops := len(path)
	amtOver := make([]lnwire.MilliSatoshi, numHops)
	expiryOver := make([]uint32, numHops)

	amtOver[numHops-1] = amt
	expiryOver[numHops-1] = finalCltvDelta

	for i := numHops - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(fwd.timeLockDelta)
	}

	hops := make([]*route.Hop, numHops)
	for i, edge := range path {
		amtToFwd := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < numHops-1 {
			amtToFwd = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToFwd,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// RequestRoute returns the next route to try: the cheapest path for the
// current shard size, halving the shard when no route exists.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.shardAmt > amt {
		r.shardAmt = amt
	}

	for {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			return rt, nil
		}

		// No route at this shard size: split if we're allowed more
		// parts and the shard is still meaningfully large.
		partsLeft := r.spec.MaxParts - inFlightHtlcs
		if partsLeft <= 1 || r.shardAmt < 10_000_000 {
			return nil, err
		}
		r.shardAmt /= 2
	}
}

// ReportAttempt learns from an attempt: liquidity failures set an upper
// bound on the failing channel.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		return nil
	}

	// Locate the failing hop and record the amount bound on its
	// outgoing channel.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			failIdx = i + 1
		}
	}

	// The failing node could not forward over its outgoing channel,
	// which is rt.Hops[failIdx].
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		hop := rt.Hops[failIdx]
		amtOver := rt.TotalAmount
		if failIdx > 0 {
			amtOver = rt.Hops[failIdx-1].AmtToForward
		}

		bound, ok := r.failedAmt[hop.ChannelID]
		if !ok || amtOver < bound {
			r.failedAmt[hop.ChannelID] = amtOver
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const candidateFinalCltvDelta = 40

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityState struct {
	upperFail lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	known     bool
	conf      float64
	failures  uint32
	successes uint32
	blocked   bool
}

var candidateKnowledge = struct {
	sync.Mutex
	states map[candidateEdgeKey]*candidateLiquidityState
}{
	states: make(map[candidateEdgeKey]*candidateLiquidityState),
}

func candidateStateSnapshot(
	key candidateEdgeKey) candidateLiquidityState {

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	state := candidateKnowledge.states[key]
	if state == nil {
		return candidateLiquidityState{}
	}

	return *state
}

func candidateMutableState(
	key candidateEdgeKey) *candidateLiquidityState {

	state := candidateKnowledge.states[key]
	if state == nil {
		state = &candidateLiquidityState{}
		candidateKnowledge.states[key] = state
	}

	return state
}

func candidateRecordProbe(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	state := candidateMutableState(edge.key)
	if amt > state.lowerOK {
		state.lowerOK = amt
	}

	highEstimate := edge.capacity * 9 / 10
	if highEstimate < amt {
		highEstimate = amt
	}
	if !state.known || state.estimate < amt {
		state.estimate = highEstimate
	}

	if state.upperFail != 0 && amt >= state.upperFail {
		state.upperFail = 0
	}
	if state.failures > 0 {
		state.failures--
	}

	state.known = true
	state.conf = math.Max(state.conf, 0.85)
	state.successes++

	reverseKey := candidateEdgeKey{
		chanID: edge.key.chanID,
		from:   edge.key.to,
		to:     edge.key.from,
	}
	reverse := candidateMutableState(reverseKey)

	reverseUpper := edge.capacity - amt + 1
	if reverseUpper < 1 {
		reverseUpper = 1
	}
	if reverse.upperFail == 0 || reverseUpper < reverse.upperFail {
		reverse.upperFail = reverseUpper
	}
	if reverse.lowerOK >= reverse.upperFail {
		reverse.lowerOK = reverse.upperFail - 1
	}
}

func candidateRecordFailure(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	state := candidateMutableState(edge.key)
	if state.upperFail == 0 || amt < state.upperFail {
		state.upperFail = amt
	}

	if state.lowerOK >= amt {
		state.lowerOK = amt - 1
	}

	depletedEstimate := amt / 8
	if depletedEstimate < state.lowerOK {
		depletedEstimate = state.lowerOK
	}
	if !state.known || state.estimate > depletedEstimate {
		state.estimate = depletedEstimate
	}

	state.known = true
	state.conf = math.Max(state.conf, 0.95)
	state.failures++

	reverseKey := candidateEdgeKey{
		chanID: edge.key.chanID,
		from:   edge.key.to,
		to:     edge.key.from,
	}
	reverse := candidateMutableState(reverseKey)

	highEstimate := edge.capacity * 9 / 10
	if highEstimate < edge.capacity-amt {
		highEstimate = edge.capacity - amt
	}
	if !reverse.known || reverse.estimate < highEstimate {
		reverse.estimate = highEstimate
	}
	reverse.known = true
	reverse.conf = math.Max(reverse.conf, 0.8)
}

func candidateBlockEdge(edge *candidateEdge) {
	if edge == nil {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	state := candidateMutableState(edge.key)
	state.blocked = true
}

func candidateRecordSettlement(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	forward := candidateMutableState(edge.key)

	preEstimate := forward.estimate
	if !forward.known {
		preEstimate = edge.capacity * 9 / 10
	}
	if preEstimate < amt {
		preEstimate = amt
	}

	forward.estimate = preEstimate - amt
	if forward.lowerOK > amt {
		forward.lowerOK -= amt
	} else {
		forward.lowerOK = 0
	}

	if forward.upperFail > amt {
		forward.upperFail -= amt
	} else {
		forward.upperFail = 0
	}

	forward.known = true
	forward.conf = math.Max(forward.conf, 0.85)
	forward.successes++
	if forward.failures > 0 {
		forward.failures--
	}

	reverseKey := candidateEdgeKey{
		chanID: edge.key.chanID,
		from:   edge.key.to,
		to:     edge.key.from,
	}
	reverse := candidateMutableState(reverseKey)

	if reverse.known {
		reverse.estimate += amt
		if reverse.estimate > edge.capacity {
			reverse.estimate = edge.capacity
		}
	} else {
		reverse.estimate = amt
	}

	reverse.lowerOK += amt
	if reverse.lowerOK > edge.capacity {
		reverse.lowerOK = edge.capacity
	}
	if reverse.upperFail != 0 {
		reverse.upperFail += amt
		if reverse.upperFail > edge.capacity {
			reverse.upperFail = edge.capacity
		}
	}

	reverse.known = true
	reverse.conf = math.Max(reverse.conf, 0.9)
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionPenalty map[candidateEdgeKey]float64
	sessionBlocked map[candidateEdgeKey]bool
	attempts       uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	router := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		sessionBlocked: make(map[candidateEdgeKey]bool),
	}

	for chanID, balance := range localBalances {
		router.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				router.incomingEdges[key.to] = append(
					router.incomingEdges[key.to], edge,
				)
				router.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

func candidatePriorProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.capacity <= 0 {
		return 0
	}

	ratio := float64(amt) / float64(edge.capacity)

	lowMode := 0.45 * math.Exp(-ratio/0.025)
	highMode := 0.50 /
		(1 + math.Exp((ratio-0.92)/0.04))

	probability := 0.025 + lowMode + highMode
	if probability > 0.985 {
		probability = 0.985
	}
	if probability < 0.005 {
		probability = 0.005
	}

	return probability
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	state := candidateStateSnapshot(edge.key)
	if state.blocked {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 1
	}

	if state.upperFail != 0 && amt >= state.upperFail {
		return 0
	}
	if state.lowerOK >= amt {
		return 0.995
	}

	prior := candidatePriorProbability(edge, amt)
	if !state.known {
		return prior
	}

	if state.estimate >= amt {
		margin := float64(state.estimate-amt+1) /
			float64(edge.capacity+1)
		probability := 0.78 + 0.17*state.conf +
			0.04*math.Min(margin, 1)

		if probability > 0.995 {
			probability = 0.995
		}

		return probability
	}

	if state.upperFail != 0 {
		relative := float64(amt) /
			float64(state.upperFail)
		if relative > 1 {
			relative = 1
		}

		probability := 0.03 +
			0.35*math.Pow(1-relative, 3) +
			0.15*prior

		if state.failures > state.successes+1 {
			probability *= 0.75
		}
		if probability < 0.01 {
			probability = 0.01
		}

		return probability
	}

	probability := 0.35 * prior
	if state.successes > state.failures {
		probability += 0.15
	}
	if probability > 0.75 {
		probability = 0.75
	}
	if probability < 0.01 {
		probability = 0.01
	}

	return probability
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateQueueItem))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

type candidateRouteChoice struct {
	route   *route.Route
	logRisk float64
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source is payment target")
	}

	dist := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = 0
	queue := &candidateQueue{}
	heap.Push(queue, &candidateQueueItem{
		node:   r.spec.Target,
		amount: deliver,
	})

	var sourceRisk float64

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateQueueItem)
		best, ok := dist[item.node]
		if !ok || item.score > best+1e-12 {
			continue
		}

		if item.node == r.source {
			sourceRisk = item.risk
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOver := item.amount
			if !edge.usable(amountOver) {
				continue
			}

			probability := r.edgeProbability(edge, amountOver)
			if probability <= 0 {
				continue
			}

			sending := amountOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOver)
				sending += fee
			}

			logRisk := -math.Log(probability) +
				r.sessionPenalty[edge.key]
			feePenalty := 15 * float64(fee) /
				math.Max(float64(deliver), 1)
			edgeScore := logRisk + feePenalty + 0.012
			newScore := item.score + edgeScore

			oldScore, exists := dist[edge.key.from]
			if exists && newScore >= oldScore {
				continue
			}

			dist[edge.key.from] = newScore
			next[edge.key.from] = edge
			heap.Push(queue, &candidateQueueItem{
				node:   edge.key.from,
				amount: sending,
				score:  newScore,
				risk:   item.risk + logRisk,
			})
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	built, err := r.buildRoute(deliver, next)
	if err != nil {
		return nil, 0, err
	}

	return built, sourceRisk, nil
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	path := make([]*candidateEdge, 0, 8)
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			nextEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	result := amt / d
	if amt%d != 0 {
		result++
	}

	return result
}

func candidateShardAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	limit := partsLeft
	if limit > 24 {
		limit = 24
	}

	amounts := make([]lnwire.MilliSatoshi, 0, limit+1)
	var previous lnwire.MilliSatoshi

	for parts := uint32(1); parts <= limit; parts++ {
		shard := candidateCeilDiv(amt, parts)
		if shard != previous {
			amounts = append(amounts, shard)
			previous = shard
		}
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	if minimum != previous {
		amounts = append(amounts, minimum)
	}

	return amounts
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= 96 {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	shards := candidateShardAmounts(amt, partsLeft)
	minimum := shards[len(shards)-1]

	threshold := 0.20
	if partsLeft <= 2 {
		threshold = 0.08
	}

	var fallback *candidateRouteChoice
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		probability := math.Exp(-logRisk)
		if probability >= threshold {
			return rt, nil
		}

		progress := math.Log(
			math.Max(float64(shard)/float64(minimum), 1),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 10 * float64(fee) /
			math.Max(float64(shard), 1)
		utility := -logRisk + 0.22*progress - feePenalty

		if fallback == nil || utility > bestUtility {
			fallback = &candidateRouteChoice{
				route:   rt,
				logRisk: logRisk,
			}
			bestUtility = utility
		}
	}

	if fallback == nil {
		return nil, errors.New("no route found")
	}

	return fallback.route, nil
}

func (r *candidateRouter) routeEdges(
	rt *route.Route) []*candidateEdge {

	edges := make([]*candidateEdge, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edges[i] = r.edges[key]
		from = hop.PubKeyBytes
	}

	return edges
}

func candidateRouteAmount(rt *route.Route,
	channelIndex int) lnwire.MilliSatoshi {

	if channelIndex == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[channelIndex-1].AmtToForward
}

func candidateFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	r.attempts++

	if rt == nil {
		return errors.New("reported route is nil")
	}

	edges := r.routeEdges(rt)

	if result.Failure == nil {
		for i, edge := range edges {
			if edge == nil {
				continue
			}

			amount := candidateRouteAmount(rt, i)
			candidateRecordSettlement(edge, amount)
			delete(r.sessionPenalty, edge.key)
		}

		if len(rt.Hops) != 0 {
			firstChan := rt.Hops[0].ChannelID
			spent := rt.TotalAmount
			if r.localBalances[firstChan] > spent {
				r.localBalances[firstChan] -= spent
			} else {
				r.localBalances[firstChan] = 0
			}
		}

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(edges) {
			prefixEnd = len(edges)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := edges[i]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordProbe(
				edge, candidateRouteAmount(rt, i),
			)
			delete(r.sessionPenalty, edge.key)
		}
	}

	code := result.Failure.Code()
	if failIndex >= 0 && failIndex < len(edges) {
		edge := edges[failIndex]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			candidateRecordFailure(
				edge, candidateRouteAmount(rt, failIndex),
			)

			retryAmount := candidateRouteAmount(
				rt, failIndex,
			) * 3 / 8
			if retryAmount > 0 {
				state := candidateStateSnapshot(edge.key)
				if state.upperFail > retryAmount {
					r.sessionPenalty[edge.key] += 0.2
				} else {
					r.sessionPenalty[edge.key] += 0.8
				}
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			candidateBlockEdge(edge)

		default:
			r.sessionBlocked[edge.key] = true
		}

		return nil
	}

	for _, edge := range edges {
		if edge == nil || edge.key.from == r.source {
			continue
		}

		r.sessionPenalty[edge.key] += 0.45
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40

	minProbability = 0.002
	maxProbability = 0.995
)

// edgeKey identifies one direction of a channel.
type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

// candidateEdge is one directed public channel.
type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

// fee returns the advertised fee for forwarding amt.
func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

// usable reports whether amt satisfies the advertised channel constraints.
func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

// liquidityBelief records amount-dependent evidence for one channel direction.
type liquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	point     lnwire.MilliSatoshi
	evidence  uint32
}

var sharedBeliefs = struct {
	sync.Mutex
	byEdge map[edgeKey]liquidityBelief
}{
	byEdge: make(map[edgeKey]liquidityBelief),
}

// candidateRouter uses amount-dependent reliability routing and persistent
// directed-channel liquidity beliefs.
type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgesByKey    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	localSpent    map[uint64]lnwire.MilliSatoshi

	policyBlocked map[edgeKey]bool
	softPenalty  map[edgeKey]float64
	routeOffers  map[uint64]uint32
	failures     uint32
}

// newCandidateRouter builds a reliability-aware router for one payment.
func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgesByKey:    make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		localSpent:    make(map[uint64]lnwire.MilliSatoshi),
		policyBlocked: make(map[edgeKey]bool),
		softPenalty:   make(map[edgeKey]float64),
		routeOffers:   make(map[uint64]uint32),
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgesByKey[key] = edge

				sharedBeliefs.Lock()
				belief := sharedBeliefs.byEdge[key]
				if belief.capacity == 0 {
					belief.capacity = edge.capacity
					sharedBeliefs.byEdge[key] = belief
				}
				sharedBeliefs.Unlock()

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

// bimodalPrior estimates the chance that a direction carries amt when no
// useful observations are available.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return minProbability
	}

	x := float64(amt) / float64(capacity)

	// The low mode decays quickly away from zero. The high mode remains
	// viable until the requested amount approaches total capacity.
	lowMode := math.Exp(-x / 0.03)
	exponent := (x - 0.92) / 0.035
	if exponent > 60 {
		exponent = 60
	} else if exponent < -60 {
		exponent = -60
	}
	highMode := 1 / (1 + math.Exp(exponent))

	p := 0.42*lowMode + 0.58*highMode
	return clampProbability(p)
}

// clampProbability keeps probability costs finite.
func clampProbability(p float64) float64 {
	if p < minProbability {
		return minProbability
	}
	if p > maxProbability {
		return maxProbability
	}

	return p
}

// beliefProbability combines the bimodal prior with accumulated evidence.
func beliefProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	prior := bimodalPrior(amt, edge.capacity)

	sharedBeliefs.Lock()
	belief, ok := sharedBeliefs.byEdge[edge.key]
	sharedBeliefs.Unlock()

	if !ok || belief.evidence == 0 {
		return prior
	}

	if belief.upperFail != 0 && amt >= belief.upperFail {
		excess := float64(amt-belief.upperFail) /
			float64(maxMSat(edge.capacity, 1))
		return clampProbability(
			minProbability * math.Exp(-8*excess),
		)
	}

	if belief.lowerOK != 0 && amt <= belief.lowerOK {
		return maxProbability
	}

	evidenceProbability := prior
	if belief.point > 0 {
		scale := float64(edge.capacity) * 0.06
		if scale < 10_000_000 {
			scale = 10_000_000
		}

		exponent := (float64(amt) - float64(belief.point)) /
			scale
		if exponent > 60 {
			exponent = 60
		} else if exponent < -60 {
			exponent = -60
		}

		evidenceProbability = 0.01 +
			0.98/(1+math.Exp(exponent))
	}

	if belief.upperFail != 0 && belief.upperFail > belief.lowerOK &&
		amt > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(amt-belief.lowerOK) / width
		if position < 0 {
			position = 0
		} else if position > 1 {
			position = 1
		}

		boundedProbability := maxProbability -
			position*(maxProbability-minProbability)
		evidenceProbability = math.Sqrt(
			clampProbability(evidenceProbability) *
				clampProbability(boundedProbability),
		)
	}

	weight := float64(belief.evidence) /
		float64(belief.evidence+2)
	p := (1-weight)*prior + weight*evidenceProbability

	return clampProbability(p)
}

// recordProbeSuccess records a channel that forwarded an HTLC which later
// failed farther along the route.
func recordProbeSuccess(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || edge.key.from == (route.Vertex{}) {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	belief := sharedBeliefs.byEdge[edge.key]
	belief.capacity = edge.capacity
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail != 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	conditional := amt +
		lnwire.MilliSatoshi(
			0.80*float64(maxMSat(edge.capacity-amt, 0)),
		)
	if conditional > belief.point {
		belief.point = conditional
	}
	if belief.point > edge.capacity {
		belief.point = edge.capacity
	}
	belief.evidence++
	sharedBeliefs.byEdge[edge.key] = belief
}

// recordLiquidityFailure records a directional upper liquidity bound.
func recordLiquidityFailure(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	belief := sharedBeliefs.byEdge[edge.key]
	belief.capacity = edge.capacity

	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	failedPoint := amt * 55 / 100
	if belief.point == 0 || failedPoint < belief.point {
		belief.point = failedPoint
	}
	belief.evidence++
	sharedBeliefs.byEdge[edge.key] = belief
}

// recordSettlement updates both directions after liquidity moves.
func (r *candidateRouter) recordSettlement(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || edge.key.from == r.source {
		return
	}

	reverseKey := edgeKey{
		chanID: edge.key.chanID,
		from:   edge.key.to,
		to:     edge.key.from,
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	forward := sharedBeliefs.byEdge[edge.key]
	forward.capacity = edge.capacity

	if amt > forward.lowerOK {
		forward.lowerOK = amt
	}
	if forward.upperFail != 0 && amt >= forward.upperFail {
		forward.upperFail = 0
	}

	conditional := amt +
		lnwire.MilliSatoshi(
			0.80*float64(maxMSat(edge.capacity-amt, 0)),
		)
	if conditional > forward.point {
		forward.point = conditional
	}

	if forward.lowerOK > amt {
		forward.lowerOK -= amt
	} else {
		forward.lowerOK = 0
	}
	if forward.upperFail > amt {
		forward.upperFail -= amt
	}
	if forward.point > amt {
		forward.point -= amt
	} else {
		forward.point = 0
	}
	forward.evidence++
	sharedBeliefs.byEdge[edge.key] = forward

	reverse, ok := sharedBeliefs.byEdge[reverseKey]
	if !ok {
		return
	}

	reverse.capacity = edge.capacity
	reverse.lowerOK = minMSat(
		reverse.capacity, reverse.lowerOK+amt,
	)
	if reverse.point == 0 {
		reverse.point = amt
	} else {
		reverse.point = minMSat(
			reverse.capacity, reverse.point+amt,
		)
	}
	if reverse.upperFail != 0 {
		reverse.upperFail = minMSat(
			reverse.capacity, reverse.upperFail+amt,
		)
	}
	if reverse.upperFail != 0 &&
		reverse.upperFail <= reverse.lowerOK {

		reverse.upperFail = 0
	}
	reverse.evidence++
	sharedBeliefs.byEdge[reverseKey] = reverse
}

// dijkstraItem is one reliability-search label.
type dijkstraItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *dijkstraQueue) Push(value any) {
	*q = append(*q, value.(*dijkstraItem))
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

// findRoute finds the best probability-weighted path for amt.
func (r *candidateRouter) findRoute(
	amt lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:   r.spec.Target,
		amount: amt,
		score:  0,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+1e-12 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if r.policyBlocked[edge.key] ||
				!edge.usable(item.amount) {

				continue
			}

			if edge.key.from == r.source {
				available := r.localBalances[edge.key.chanID] -
					r.localSpent[edge.key.chanID]
				if available < item.amount {
					continue
				}
			}

			sending := item.amount
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.amount)
				sending += fee
			}
			if sending <= 0 {
				continue
			}

			probability := maxProbability
			if edge.key.from != r.source {
				probability = beliefProbability(edge, item.amount)
			}

			feeRatio := float64(fee) /
				float64(maxMSat(amt, 1))
			edgeScore := -math.Log(probability) +
				8*feeRatio + 0.015 +
				r.softPenalty[edge.key]
			score := item.score + edgeScore

			oldScore, exists := bestScore[edge.key.from]
			if exists && score >= oldScore {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &dijkstraItem{
				node:   edge.key.from,
				amount: sending,
				score:  score,
			})
		}
	}

	score, ok := bestScore[r.source]
	if !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, score, nil
}

// buildRoute converts path pointers into the simulator's route encoding.
func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("routing cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] +
			outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmount := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			forwardAmount = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmount,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// RequestRoute jointly chooses a feasible shard count and its best route.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.spec.MaxParts == 0 || inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("no payment parts remaining")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs

	var (
		bestRoute     *route.Route
		bestObjective = math.Inf(1)
		bestParts     uint32
		lastErr       error
	)

	for parts := uint32(1); parts <= partsLeft; parts++ {
		shard := ceilDivide(amt, parts)
		rt, score, err := r.findRoute(shard)
		if err != nil {
			lastErr = err
			continue
		}

		hash := routeHash(rt)
		reusePenalty := 0.45 * float64(r.routeOffers[hash])

		// This approximates the probability that every required shard
		// completes while mildly preferring fewer attempts and lower fees.
		objective := float64(parts)*score +
			0.12*float64(parts-1) + reusePenalty

		if objective < bestObjective ||
			(objective == bestObjective && parts < bestParts) {

			bestRoute = rt
			bestObjective = objective
			bestParts = parts
		}
	}

	if bestRoute == nil {
		if lastErr != nil {
			return nil, lastErr
		}
		return nil, errors.New("no route found")
	}

	r.routeOffers[routeHash(bestRoute)]++
	return bestRoute, nil
}

// ReportAttempt incorporates directional liquidity and policy feedback.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	edges, amounts := r.routeEdges(rt)

	if result.Failure == nil {
		if len(edges) != 0 {
			r.localSpent[edges[0].key.chanID] += amounts[0]
		}
		for i, edge := range edges {
			r.recordSettlement(edge, amounts[i])
		}

		return nil
	}

	r.failures++

	failEdge := r.failureEdgeIndex(rt, result.FailureSource)
	code, hasCode := failureCode(result.Failure)

	if failEdge >= 0 {
		for i := 0; i < failEdge && i < len(edges); i++ {
			if edges[i].key.from != r.source {
				recordProbeSuccess(edges[i], amounts[i])
			}
		}
	}

	switch {
	case hasCode && code == lnwire.CodeTemporaryChannelFailure:
		if failEdge >= 0 && failEdge < len(edges) {
			edge := edges[failEdge]
			recordLiquidityFailure(edge, amounts[failEdge])
			r.softPenalty[edge.key] += 0.75
		} else {
			r.penalizeUnknownRoute(edges, 0.80)
		}

	case hasCode && (code == lnwire.CodeFeeInsufficient ||
		code == lnwire.CodeIncorrectCltvExpiry):

		if failEdge >= 0 && failEdge < len(edges) {
			r.policyBlocked[edges[failEdge].key] = true
		} else {
			r.penalizeUnknownRoute(edges, 0.50)
		}

	default:
		r.penalizeUnknownRoute(edges, 0.20)
	}

	return nil
}

// failureEdgeIndex maps a failing node to its outgoing route channel.
func (r *candidateRouter) failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

// routeEdges reconstructs directed edges and channel amounts from a route.
func (r *candidateRouter) routeEdges(
	rt *route.Route) ([]*candidateEdge, []lnwire.MilliSatoshi) {

	edges := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgesByKey[key]
		if edge == nil {
			edge = &candidateEdge{
				key: key,
			}
		}

		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		edges = append(edges, edge)
		amounts = append(amounts, amt)
		from = hop.PubKeyBytes
	}

	return edges, amounts
}

// penalizeUnknownRoute encourages exploration when the failure source is
// unavailable or cannot be mapped to a directed channel.
func (r *candidateRouter) penalizeUnknownRoute(
	edges []*candidateEdge, total float64) {

	if len(edges) == 0 {
		return
	}

	perEdge := total / math.Sqrt(float64(len(edges)))
	for _, edge := range edges {
		r.softPenalty[edge.key] += perEdge
	}
}

// failureCode extracts a wire failure code without depending on a concrete
// failure message type.
func failureCode(failure any) (lnwire.FailCode, bool) {
	coder, ok := failure.(interface {
		Code() lnwire.FailCode
	})
	if !ok {
		return 0, false
	}

	return coder.Code(), true
}

// routeHash identifies a channel path at a particular amount.
func routeHash(rt *route.Route) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	mix := func(value uint64) {
		for i := 0; i < 8; i++ {
			hash ^= value & 0xff
			hash *= prime
			value >>= 8
		}
	}

	mix(uint64(rt.TotalAmount))
	for _, hop := range rt.Hops {
		mix(hop.ChannelID)
	}

	return hash
}

// ceilDivide returns ceil(amount/divisor) without overflowing amount.
func ceilDivide(amount lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	d := lnwire.MilliSatoshi(divisor)
	result := amount / d
	if amount%d != 0 {
		result++
	}

	return result
}

func minMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a < b {
		return a
	}

	return b
}

func maxMSat(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a > b {
		return a
	}

	return b
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	candidateFinalCltvDelta = 40
	candidateMaxAttempts    = 96
	candidateMaxLabels      = 8
	candidateMaxHops        = 40
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type candidateLiquidityState struct {
	upperFail lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	known     bool
	conf      float64
	failures  uint32
	successes uint32
}

var candidateKnowledge = struct {
	sync.Mutex
	states map[candidateEdgeKey]*candidateLiquidityState
}{
	states: make(map[candidateEdgeKey]*candidateLiquidityState),
}

func candidateMutableState(
	key candidateEdgeKey) *candidateLiquidityState {

	state := candidateKnowledge.states[key]
	if state == nil {
		state = &candidateLiquidityState{}
		candidateKnowledge.states[key] = state
	}

	return state
}

func candidateStateSnapshot(
	key candidateEdgeKey) candidateLiquidityState {

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	state := candidateKnowledge.states[key]
	if state == nil {
		return candidateLiquidityState{}
	}

	return *state
}

func candidateReverseKey(edge *candidateEdge) candidateEdgeKey {
	return candidateEdgeKey{
		chanID: edge.key.chanID,
		from:   edge.key.to,
		to:     edge.key.from,
	}
}

func candidateRecordProbe(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	state := candidateMutableState(edge.key)
	if amt > state.lowerOK {
		state.lowerOK = amt
	}

	estimate := edge.capacity * 9 / 10
	if estimate < amt {
		estimate = amt
	}
	if !state.known || estimate > state.estimate {
		state.estimate = estimate
	}

	if state.upperFail != 0 && amt >= state.upperFail {
		state.upperFail = 0
	}
	if state.failures > 0 {
		state.failures--
	}

	state.known = true
	state.conf = math.Max(state.conf, 0.88)
	state.successes++

	reverse := candidateMutableState(candidateReverseKey(edge))
	reverseUpper := edge.capacity - amt + 1
	if reverseUpper < 1 {
		reverseUpper = 1
	}
	if reverse.upperFail == 0 || reverseUpper < reverse.upperFail {
		reverse.upperFail = reverseUpper
	}
	if reverse.lowerOK >= reverse.upperFail {
		reverse.lowerOK = reverse.upperFail - 1
	}

	if !reverse.known || reverse.estimate >= reverseUpper {
		reverse.estimate = reverseUpper - 1
	}
	reverse.known = true
	reverse.conf = math.Max(reverse.conf, 0.80)
}

func candidateRecordFailure(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	state := candidateMutableState(edge.key)
	if state.upperFail == 0 || amt < state.upperFail {
		state.upperFail = amt
	}

	if state.lowerOK >= amt {
		state.lowerOK = amt - 1
	}

	estimate := amt / 6
	if estimate < state.lowerOK {
		estimate = state.lowerOK
	}
	if !state.known || estimate < state.estimate {
		state.estimate = estimate
	}

	state.known = true
	state.conf = math.Max(state.conf, 0.96)
	state.failures++

	reverse := candidateMutableState(candidateReverseKey(edge))
	reverseLower := edge.capacity - amt + 1
	if reverseLower < 0 {
		reverseLower = 0
	}
	if reverseLower > edge.capacity {
		reverseLower = edge.capacity
	}
	if reverseLower > reverse.lowerOK {
		reverse.lowerOK = reverseLower
	}

	estimate = edge.capacity * 9 / 10
	if estimate < reverseLower {
		estimate = reverseLower
	}
	if !reverse.known || estimate > reverse.estimate {
		reverse.estimate = estimate
	}

	if reverse.upperFail != 0 &&
		reverse.upperFail <= reverse.lowerOK {

		reverse.upperFail = 0
	}

	reverse.known = true
	reverse.conf = math.Max(reverse.conf, 0.88)
	reverse.successes++
}

func candidateRecordSettlement(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	candidateKnowledge.Lock()
	defer candidateKnowledge.Unlock()

	forward := candidateMutableState(edge.key)

	preEstimate := forward.estimate
	if !forward.known {
		preEstimate = edge.capacity * 9 / 10
	}
	if preEstimate < amt {
		preEstimate = amt
	}

	forward.estimate = preEstimate - amt
	if forward.lowerOK > amt {
		forward.lowerOK -= amt
	} else {
		forward.lowerOK = 0
	}

	if forward.upperFail > amt {
		forward.upperFail -= amt
	} else {
		forward.upperFail = 0
	}

	forward.known = true
	forward.conf = math.Max(forward.conf, 0.90)
	forward.successes++
	if forward.failures > 0 {
		forward.failures--
	}

	reverse := candidateMutableState(candidateReverseKey(edge))
	if reverse.known {
		reverse.estimate += amt
	} else {
		reverse.estimate = amt
	}
	if reverse.estimate > edge.capacity {
		reverse.estimate = edge.capacity
	}

	reverse.lowerOK += amt
	if reverse.lowerOK > edge.capacity {
		reverse.lowerOK = edge.capacity
	}

	if reverse.upperFail != 0 {
		reverse.upperFail += amt
		if reverse.upperFail > edge.capacity {
			reverse.upperFail = 0
		}
	}

	reverse.known = true
	reverse.conf = math.Max(reverse.conf, 0.92)
	reverse.successes++
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionPenalty map[candidateEdgeKey]float64
	sessionBlocked map[candidateEdgeKey]bool

	shardCeiling       lnwire.MilliSatoshi
	consecutiveFailure uint32
	attempts           uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("payment specification is nil")
	}

	router := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  make(map[uint64]lnwire.MilliSatoshi),
		sessionPenalty: make(map[candidateEdgeKey]float64),
		sessionBlocked: make(map[candidateEdgeKey]bool),
	}

	for chanID, balance := range localBalances {
		router.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				router.incomingEdges[key.to] = append(
					router.incomingEdges[key.to], edge,
				)
				router.edges[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

func candidateClampProbability(probability float64) float64 {
	switch {
	case probability < 0.003:
		return 0.003

	case probability > 0.997:
		return 0.997

	default:
		return probability
	}
}

func candidatePriorProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.capacity <= 0 || amt <= 0 {
		return 0
	}

	ratio := float64(amt) / float64(edge.capacity)
	lowMode := 0.46 * math.Exp(-ratio/0.022)
	highMode := 0.505 /
		(1 + math.Exp((ratio-0.92)/0.038))

	return candidateClampProbability(
		0.018 + lowMode + highMode,
	)
}

func (r *candidateRouter) edgeProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return 1
	}

	state := candidateStateSnapshot(edge.key)
	if state.upperFail != 0 && amt >= state.upperFail {
		return 0
	}
	if state.lowerOK >= amt {
		return 0.997
	}

	prior := candidatePriorProbability(edge, amt)
	if !state.known {
		return prior
	}

	probability := prior

	if state.upperFail != 0 {
		lower := state.lowerOK
		upper := state.upperFail
		span := upper - lower

		if span <= 1 {
			return 0.004
		}

		position := float64(amt-lower) / float64(span)
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		bounded := 0.008 +
			0.974*math.Pow(1-position, 1.75)
		weight := 0.58 + 0.07*float64(state.failures)
		if weight > 0.90 {
			weight = 0.90
		}

		probability = (1-weight)*prior + weight*bounded
	}

	if state.estimate >= amt {
		margin := float64(state.estimate-amt+1) /
			float64(edge.capacity+1)
		estimateProbability := 0.86 +
			0.11*state.conf +
			0.025*math.Min(margin*4, 1)

		if estimateProbability > probability {
			probability = estimateProbability
		}
	} else if state.upperFail == 0 {
		probability = 0.30*prior + 0.08
	}

	if state.failures > state.successes+2 {
		probability *= 0.82
	}

	return candidateClampProbability(probability)
}

type candidateLabel struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	risk   float64
	hops   int

	edge   *candidateEdge
	suffix *candidateLabel
	active bool
}

type candidateQueue []*candidateLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateQueue) Push(value any) {
	*q = append(*q, value.(*candidateLabel))
}

func (q *candidateQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func candidateAddLabel(labels map[route.Vertex][]*candidateLabel,
	label *candidateLabel, deliver lnwire.MilliSatoshi) bool {

	current := labels[label.node]
	for _, other := range current {
		if !other.active {
			continue
		}
		if other.score <= label.score+1e-12 &&
			other.amount <= label.amount {

			return false
		}
	}

	for _, other := range current {
		if !other.active {
			continue
		}
		if label.score <= other.score+1e-12 &&
			label.amount <= other.amount {

			other.active = false
		}
	}

	label.active = true
	current = append(current, label)
	labels[label.node] = current

	activeCount := 0
	for _, other := range current {
		if other.active {
			activeCount++
		}
	}
	if activeCount <= candidateMaxLabels {
		return true
	}

	var worst *candidateLabel
	worstRank := math.Inf(-1)
	for _, other := range current {
		if !other.active {
			continue
		}

		ratio := float64(other.amount) /
			math.Max(float64(deliver), 1)
		rank := other.score + 0.08*math.Log1p(ratio)
		if rank > worstRank {
			worstRank = rank
			worst = other
		}
	}

	if worst != nil {
		worst.active = false
	}

	return label.active
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, error) {

	if deliver <= 0 {
		return nil, 0, errors.New("route amount must be positive")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source is payment target")
	}

	start := &candidateLabel{
		node:   r.spec.Target,
		amount: deliver,
		active: true,
	}
	labels := map[route.Vertex][]*candidateLabel{
		r.spec.Target: {start},
	}
	queue := &candidateQueue{}
	heap.Push(queue, start)

	for queue.Len() != 0 {
		item := heap.Pop(queue).(*candidateLabel)
		if !item.active {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(deliver, item)
			if err != nil {
				return nil, 0, err
			}

			return rt, item.risk, nil
		}

		if item.hops >= candidateMaxHops {
			continue
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOver := item.amount
			if !edge.usable(amountOver) {
				continue
			}

			probability := r.edgeProbability(edge, amountOver)
			if probability <= 0 {
				continue
			}

			sending := amountOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOver)
				if fee < 0 || sending > math.MaxInt64-fee {
					continue
				}
				sending += fee
			}

			edgeRisk := -math.Log(probability) +
				r.sessionPenalty[edge.key]
			feePenalty := 3.5 * float64(fee) /
				math.Max(float64(deliver), 1)

			label := &candidateLabel{
				node:   edge.key.from,
				amount: sending,
				score: item.score + edgeRisk +
					feePenalty + 0.006,
				risk:   item.risk + edgeRisk,
				hops:   item.hops + 1,
				edge:   edge,
				suffix: item,
			}

			if !candidateAddLabel(labels, label, deliver) {
				continue
			}

			heap.Push(queue, label)
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(deliver lnwire.MilliSatoshi,
	sourceLabel *candidateLabel) (*route.Route, error) {

	path := make([]*candidateEdge, 0, sourceLabel.hops)
	visited := make(map[route.Vertex]bool)
	label := sourceLabel
	node := r.source

	for node != r.spec.Target {
		if label == nil || label.edge == nil {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		if visited[node] {
			return nil, errors.New("cycle in selected route")
		}
		visited[node] = true

		if label.edge.key.from != node {
			return nil, fmt.Errorf("misdirected path at %v", node)
		}

		path = append(path, label.edge)
		node = label.edge.key.to
		label = label.suffix
	}

	if len(path) == 0 {
		return nil, errors.New("selected route has no hops")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = candidateFinalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		fee := nextEdge.fee(amounts[i+1])
		if fee < 0 || amounts[i+1] > math.MaxInt64-fee {
			return nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := deliver
		outgoingExpiry := uint32(candidateFinalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateCeilDiv(amt lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amt
	}

	d := lnwire.MilliSatoshi(divisor)
	result := amt / d
	if amt%d != 0 {
		result++
	}

	return result
}

func candidateAppendShard(amounts []lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, shard,
	minimum, maximum lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if shard < minimum || shard > maximum || seen[shard] {
		return amounts
	}

	seen[shard] = true
	return append(amounts, shard)
}

func candidateShardAmounts(amt lnwire.MilliSatoshi,
	partsLeft uint32,
	ceiling lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := candidateCeilDiv(amt, partsLeft)
	maximum := amt
	if ceiling > 0 && ceiling < maximum {
		maximum = ceiling
	}
	if maximum < minimum {
		maximum = minimum
	}

	amounts := make([]lnwire.MilliSatoshi, 0, 24)
	seen := make(map[lnwire.MilliSatoshi]bool)

	amounts = candidateAppendShard(
		amounts, seen, maximum, minimum, maximum,
	)
	amounts = candidateAppendShard(
		amounts, seen, maximum*4/5, minimum, maximum,
	)
	amounts = candidateAppendShard(
		amounts, seen, maximum*2/3, minimum, maximum,
	)
	amounts = candidateAppendShard(
		amounts, seen, maximum/2, minimum, maximum,
	)

	firstParts := uint32(1)
	if maximum < amt {
		firstParts = uint32(
			(int64(amt) + int64(maximum) - 1) /
				int64(maximum),
		)
		if firstParts < 1 {
			firstParts = 1
		}
	}

	limit := partsLeft
	if limit > firstParts+19 {
		limit = firstParts + 19
	}

	for parts := firstParts; parts <= limit; parts++ {
		amounts = candidateAppendShard(
			amounts, seen, candidateCeilDiv(amt, parts),
			minimum, maximum,
		)
	}

	amounts = candidateAppendShard(
		amounts, seen, minimum, minimum, maximum,
	)

	sort.Slice(amounts, func(i, j int) bool {
		return amounts[i] > amounts[j]
	})

	return amounts
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("remaining amount must be positive")
	}
	if r.attempts >= candidateMaxAttempts {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts reached")
	}

	partsLeft := maxParts - inFlightHtlcs
	shards := candidateShardAmounts(
		amt, partsLeft, r.shardCeiling,
	)
	minimum := candidateCeilDiv(amt, partsLeft)

	progressWeight := 0.34
	if r.consecutiveFailure != 0 {
		progressWeight = 0.18
	}

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)
	var bestShard lnwire.MilliSatoshi

	for _, shard := range shards {
		rt, logRisk, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		progress := math.Log(
			math.Max(float64(shard)/float64(minimum), 1),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 3.5 * float64(fee) /
			math.Max(float64(shard), 1)
		utility := -logRisk +
			progressWeight*progress - feePenalty

		if bestRoute == nil || utility > bestUtility+1e-12 ||
			(math.Abs(utility-bestUtility) <= 1e-12 &&
				shard > bestShard) {

			bestRoute = rt
			bestUtility = utility
			bestShard = shard
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	return bestRoute, nil
}

func (r *candidateRouter) routeEdges(
	rt *route.Route) []*candidateEdge {

	edges := make([]*candidateEdge, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := candidateEdgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edges[i] = r.edges[key]
		from = hop.PubKeyBytes
	}

	return edges
}

func candidateRouteAmount(rt *route.Route,
	channelIndex int) lnwire.MilliSatoshi {

	if channelIndex == 0 {
		return rt.TotalAmount
	}

	return rt.Hops[channelIndex-1].AmtToForward
}

func candidateDeliveredAmount(
	rt *route.Route) lnwire.MilliSatoshi {

	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateFailureIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) reduceShardCeiling(
	deliver lnwire.MilliSatoshi, numerator,
	denominator int64) {

	if deliver <= 0 || numerator <= 0 || denominator <= 0 {
		return
	}

	next := lnwire.MilliSatoshi(
		int64(deliver) * numerator / denominator,
	)
	if next < 1 {
		next = 1
	}

	if r.shardCeiling == 0 || next < r.shardCeiling {
		r.shardCeiling = next
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	r.attempts++

	if rt == nil {
		return errors.New("reported route is nil")
	}

	edges := r.routeEdges(rt)
	deliver := candidateDeliveredAmount(rt)

	if result.Failure == nil {
		for i, edge := range edges {
			if edge == nil {
				continue
			}

			candidateRecordSettlement(
				edge, candidateRouteAmount(rt, i),
			)
			delete(r.sessionPenalty, edge.key)
		}

		if len(rt.Hops) != 0 {
			firstChan := rt.Hops[0].ChannelID
			spent := rt.TotalAmount
			if r.localBalances[firstChan] > spent {
				r.localBalances[firstChan] -= spent
			} else {
				r.localBalances[firstChan] = 0
			}
		}

		if deliver > 0 {
			next := deliver + deliver/5
			if r.shardCeiling == 0 || next > r.shardCeiling {
				r.shardCeiling = next
			}
		}
		r.consecutiveFailure = 0

		return nil
	}

	failIndex := candidateFailureIndex(
		rt, result.FailureSource,
	)

	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(edges) {
			prefixEnd = len(edges)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := edges[i]
			if edge == nil || edge.key.from == r.source {
				continue
			}

			candidateRecordProbe(
				edge, candidateRouteAmount(rt, i),
			)
			delete(r.sessionPenalty, edge.key)
		}
	}

	code := result.Failure.Code()
	if failIndex >= 0 && failIndex < len(edges) {
		edge := edges[failIndex]
		if edge == nil {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			failedAmount := candidateRouteAmount(
				rt, failIndex,
			)
			candidateRecordFailure(edge, failedAmount)

			if edge.key.from == r.source &&
				failedAmount <=
					r.localBalances[edge.key.chanID] {

				r.localBalances[edge.key.chanID] =
					failedAmount - 1
			}

			r.sessionPenalty[edge.key] += 0.05
			r.reduceShardCeiling(deliver, 1, 3)
			r.consecutiveFailure++

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[edge.key] = true
			r.sessionPenalty[edge.key] += 4

		default:
			r.sessionPenalty[edge.key] += 1.2
			r.reduceShardCeiling(deliver, 3, 5)
			r.consecutiveFailure++
		}

		return nil
	}

	for _, edge := range edges {
		if edge == nil || edge.key.from == r.source {
			continue
		}

		r.sessionPenalty[edge.key] += 0.28
	}

	if code == lnwire.CodeTemporaryChannelFailure {
		r.reduceShardCeiling(deliver, 1, 2)
	} else {
		r.reduceShardCeiling(deliver, 3, 5)
	}
	r.consecutiveFailure++

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const (
	finalCltvDelta = 40
	attemptLimit   = 80
	maxRouteHops   = 24
	maxNodeLabels  = 8

	minProbability = 0.0005
	maxProbability = 0.999
)

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(
	amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	const million = lnwire.MilliSatoshi(1_000_000)

	proportional := (amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million

	return e.baseFeeMsat + proportional
}

func (e *candidateEdge) usable(
	amt lnwire.MilliSatoshi) bool {

	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}

	return true
}

type liquidityBelief struct {
	capacity  lnwire.MilliSatoshi
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	point     lnwire.MilliSatoshi

	confidence float64
	evidence   uint32
	mode       int8
}

var sharedBeliefs = struct {
	sync.Mutex
	byEdge map[edgeKey]liquidityBelief
}{
	byEdge: make(map[edgeKey]liquidityBelief),
}

func reverseKey(key edgeKey) edgeKey {
	return edgeKey{
		chanID: key.chanID,
		from:   key.to,
		to:     key.from,
	}
}

func normalizeBelief(
	belief *liquidityBelief,
	capacity lnwire.MilliSatoshi) {

	belief.capacity = capacity

	if belief.lowerOK < 0 {
		belief.lowerOK = 0
	}
	if belief.lowerOK > capacity {
		belief.lowerOK = capacity
	}

	if belief.upperFail < 0 || belief.upperFail > capacity {
		belief.upperFail = 0
	}
	if belief.upperFail != 0 &&
		belief.lowerOK >= belief.upperFail {

		belief.upperFail = 0
	}

	if belief.point < belief.lowerOK {
		belief.point = belief.lowerOK
	}
	if belief.point > capacity {
		belief.point = capacity
	}
	if belief.point < 0 {
		belief.point = 0
	}
	if belief.upperFail != 0 &&
		belief.point >= belief.upperFail {

		belief.point = belief.upperFail - 1
		if belief.point < belief.lowerOK {
			belief.point = belief.lowerOK
		}
	}

	belief.mode = 0
	if capacity > 0 {
		switch {
		case belief.point <= capacity/50:
			belief.mode = -1

		case belief.point >= capacity*49/50:
			belief.mode = 1
		}
	}
}

func beliefSnapshot(edge *candidateEdge) liquidityBelief {
	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	belief, ok := sharedBeliefs.byEdge[edge.key]
	if !ok || belief.capacity != edge.capacity {
		return liquidityBelief{
			capacity: edge.capacity,
		}
	}

	normalizeBelief(&belief, edge.capacity)
	return belief
}

func strongObservation(
	amt, capacity lnwire.MilliSatoshi) bool {

	if capacity <= 0 {
		return false
	}

	threshold := capacity / 200
	if threshold < 1 {
		threshold = 1
	}

	return amt >= threshold
}

func recordProbeSuccess(
	edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	forward := sharedBeliefs.byEdge[edge.key]
	if forward.capacity != edge.capacity {
		forward = liquidityBelief{
			capacity: edge.capacity,
		}
	}

	if amt > forward.lowerOK {
		forward.lowerOK = amt
	}
	if forward.upperFail != 0 &&
		forward.lowerOK >= forward.upperFail {

		forward.upperFail = 0
	}

	inferred := amt
	if strongObservation(amt, edge.capacity) {
		richPoint := edge.capacity * 97 / 100
		if richPoint > inferred {
			inferred = richPoint
		}
	}
	if inferred > forward.point {
		forward.point = inferred
	}

	forward.confidence = math.Max(forward.confidence, 0.94)
	forward.evidence++
	normalizeBelief(&forward, edge.capacity)
	sharedBeliefs.byEdge[edge.key] = forward

	key := reverseKey(edge.key)
	reverse := sharedBeliefs.byEdge[key]
	if reverse.capacity != edge.capacity {
		reverse = liquidityBelief{
			capacity: edge.capacity,
		}
	}

	reverseUpper := edge.capacity - amt + 1
	if reverseUpper < 1 {
		reverseUpper = 1
	}
	if reverse.upperFail == 0 ||
		reverseUpper < reverse.upperFail {

		reverse.upperFail = reverseUpper
	}
	if reverse.lowerOK >= reverse.upperFail {
		reverse.lowerOK = reverse.upperFail - 1
	}

	reversePoint := edge.capacity - forward.point
	if reverse.evidence == 0 || reversePoint < reverse.point {
		reverse.point = reversePoint
	}

	reverse.confidence = math.Max(reverse.confidence, 0.86)
	reverse.evidence++
	normalizeBelief(&reverse, edge.capacity)
	sharedBeliefs.byEdge[key] = reverse
}

func recordLiquidityFailure(
	edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	forward := sharedBeliefs.byEdge[edge.key]
	if forward.capacity != edge.capacity {
		forward = liquidityBelief{
			capacity: edge.capacity,
		}
	}

	if forward.upperFail == 0 || amt < forward.upperFail {
		forward.upperFail = amt
	}
	if forward.lowerOK >= amt {
		forward.lowerOK = amt - 1
	}

	dryPoint := amt / 32
	if strongObservation(amt, edge.capacity) {
		capFloor := edge.capacity / 1000
		if capFloor < 1 {
			capFloor = 1
		}
		if dryPoint > capFloor {
			dryPoint = capFloor
		}
	}
	if dryPoint < forward.lowerOK {
		dryPoint = forward.lowerOK
	}
	if forward.evidence == 0 || dryPoint < forward.point {
		forward.point = dryPoint
	}

	forward.confidence = math.Max(forward.confidence, 0.99)
	forward.evidence++
	normalizeBelief(&forward, edge.capacity)
	sharedBeliefs.byEdge[edge.key] = forward

	key := reverseKey(edge.key)
	reverse := sharedBeliefs.byEdge[key]
	if reverse.capacity != edge.capacity {
		reverse = liquidityBelief{
			capacity: edge.capacity,
		}
	}

	reverseLower := edge.capacity - amt + 1
	if reverseLower < 0 {
		reverseLower = 0
	}
	if reverseLower > reverse.lowerOK {
		reverse.lowerOK = reverseLower
	}
	if reverse.upperFail != 0 &&
		reverse.lowerOK >= reverse.upperFail {

		reverse.upperFail = 0
	}

	reversePoint := edge.capacity - forward.point
	if reversePoint < reverse.lowerOK {
		reversePoint = reverse.lowerOK
	}
	if reversePoint > reverse.point {
		reverse.point = reversePoint
	}

	reverse.confidence = math.Max(reverse.confidence, 0.97)
	reverse.evidence++
	normalizeBelief(&reverse, edge.capacity)
	sharedBeliefs.byEdge[key] = reverse
}

func recordSettlement(
	edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	if edge == nil || amt <= 0 {
		return
	}

	sharedBeliefs.Lock()
	defer sharedBeliefs.Unlock()

	forward := sharedBeliefs.byEdge[edge.key]
	if forward.capacity != edge.capacity {
		forward = liquidityBelief{
			capacity: edge.capacity,
		}
	}

	prePoint := forward.point
	if prePoint < amt {
		prePoint = amt
	}
	if strongObservation(amt, edge.capacity) {
		richPoint := edge.capacity * 97 / 100
		if richPoint > prePoint {
			prePoint = richPoint
		}
	}
	if prePoint > edge.capacity {
		prePoint = edge.capacity
	}

	forward.point = prePoint - amt
	if forward.lowerOK > amt {
		forward.lowerOK -= amt
	} else {
		forward.lowerOK = 0
	}
	if forward.upperFail > amt {
		forward.upperFail -= amt
	} else {
		forward.upperFail = 0
	}

	forward.confidence = math.Max(forward.confidence, 0.96)
	forward.evidence++
	normalizeBelief(&forward, edge.capacity)
	sharedBeliefs.byEdge[edge.key] = forward

	key := reverseKey(edge.key)
	reverse := sharedBeliefs.byEdge[key]
	if reverse.capacity != edge.capacity {
		reverse = liquidityBelief{
			capacity: edge.capacity,
		}
	}

	reverse.lowerOK = minMSat(
		edge.capacity, reverse.lowerOK+amt,
	)
	if reverse.upperFail != 0 {
		if reverse.upperFail > edge.capacity-amt {
			reverse.upperFail = 0
		} else {
			reverse.upperFail += amt
		}
	}

	reverse.point = edge.capacity - forward.point
	if reverse.point < reverse.lowerOK {
		reverse.point = reverse.lowerOK
	}

	reverse.confidence = math.Max(reverse.confidence, 0.96)
	reverse.evidence++
	normalizeBelief(&reverse, edge.capacity)
	sharedBeliefs.byEdge[key] = reverse
}

func priorSurvival(
	amt, capacity lnwire.MilliSatoshi) float64 {

	if amt <= 0 {
		return maxProbability
	}
	if capacity <= 0 || amt > capacity {
		return 0
	}

	ratio := float64(amt) / float64(capacity)
	lowMode := 0.495 * math.Exp(-ratio/0.018)

	exponent := (ratio - 0.965) / 0.018
	if exponent > 60 {
		exponent = 60
	} else if exponent < -60 {
		exponent = -60
	}

	highMode := 0.495 / (1 + math.Exp(exponent))
	return clampProbability(0.005 + lowMode + highMode)
}

func clampProbability(probability float64) float64 {
	if probability < minProbability {
		return minProbability
	}
	if probability > maxProbability {
		return maxProbability
	}

	return probability
}

func lowModeProbability(
	edge *candidateEdge,
	belief liquidityBelief,
	amt lnwire.MilliSatoshi) float64 {

	scale := math.Max(float64(edge.capacity)*0.018, 1)
	distance := float64(amt - belief.lowerOK)
	if distance < 0 {
		distance = 0
	}

	tail := math.Exp(-distance / scale)
	if belief.upperFail != 0 {
		upperDistance := float64(
			belief.upperFail - belief.lowerOK,
		)
		upperTail := math.Exp(-upperDistance / scale)
		if upperTail < 0.999999 {
			tail = (tail - upperTail) / (1 - upperTail)
			if tail < 0 {
				tail = 0
			}
		}
	}

	probability := 0.006 + 0.86*tail
	if belief.point >= amt {
		probability = math.Max(probability, 0.88)
	}

	return clampProbability(probability)
}

func beliefProbability(
	edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	belief := beliefSnapshot(edge)
	if belief.upperFail != 0 && amt >= belief.upperFail {
		return 0
	}
	if belief.lowerOK >= amt {
		return maxProbability
	}

	prior := priorSurvival(amt, edge.capacity)
	if belief.evidence == 0 {
		return prior
	}

	var bounded = prior
	switch {
	case belief.upperFail != 0:
		lowerSurvival := priorSurvival(
			belief.lowerOK, edge.capacity,
		)
		upperSurvival := priorSurvival(
			belief.upperFail, edge.capacity,
		)
		denominator := lowerSurvival - upperSurvival
		if denominator > 1e-12 {
			bounded = (prior - upperSurvival) / denominator
			if bounded < 0 {
				bounded = 0
			}
		}

	case belief.lowerOK > 0:
		lowerSurvival := priorSurvival(
			belief.lowerOK, edge.capacity,
		)
		if lowerSurvival > 1e-12 {
			bounded = prior / lowerSurvival
		}
	}

	var evidenceProbability float64
	switch {
	case belief.mode < 0:
		evidenceProbability = lowModeProbability(
			edge, belief, amt,
		)

	case belief.point >= amt:
		margin := float64(belief.point-amt+1) /
			math.Max(float64(edge.capacity), 1)
		evidenceProbability = 0.80 +
			0.18*belief.confidence +
			0.015*math.Min(margin*5, 1)

	default:
		shortfall := float64(amt-belief.point) /
			math.Max(float64(edge.capacity), 1)
		evidenceProbability = bounded *
			(1-0.82*belief.confidence) *
			math.Exp(-shortfall/0.035)
	}

	weight := float64(belief.evidence) /
		float64(belief.evidence+1)
	probability := (1-weight)*bounded +
		weight*evidenceProbability

	return clampProbability(probability)
}

func lowerRetryFactor(
	amt, failedAt lnwire.MilliSatoshi) float64 {

	if failedAt == 0 {
		return 1
	}
	if amt >= failedAt {
		return 0
	}

	ratio := float64(amt) / float64(failedAt)
	switch {
	case ratio > 0.75:
		return 0.004

	case ratio > 0.40:
		return 0.02

	case ratio > 0.15:
		return 0.09

	case ratio > 0.04:
		return 0.34

	case ratio > 0.01:
		return 0.65

	default:
		return 0.90
	}
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgesByKey    map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	sessionPenalty  map[edgeKey]float64
	sessionBlocked  map[edgeKey]bool
	sessionFailedAt map[edgeKey]lnwire.MilliSatoshi

	attempts        uint32
	failedAttempts  uint32
	successfulParts uint32
}

func newCandidateRouter(
	view routing.SimNetworkView,
	source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	router := &candidateRouter{
		source:          source,
		spec:            spec,
		incomingEdges:   make(map[route.Vertex][]*candidateEdge),
		edgesByKey:      make(map[edgeKey]*candidateEdge),
		localBalances:   make(map[uint64]lnwire.MilliSatoshi),
		sessionPenalty:  make(map[edgeKey]float64),
		sessionBlocked:  make(map[edgeKey]bool),
		sessionFailedAt: make(map[edgeKey]lnwire.MilliSatoshi),
	}

	for chanID, balance := range localBalances {
		router.localBalances[chanID] = balance
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{
		source: true,
	}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: policy.FeeBaseMSat,
					feeRatePPM: policy.
						FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				router.incomingEdges[node] = append(
					router.incomingEdges[node], edge,
				)
				router.edgesByKey[key] = edge

				return nil
			},
			func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

func (r *candidateRouter) edgeProbability(
	edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if r.sessionBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if amt <= 0 || amt > edge.capacity {
			return 0
		}
		if r.localBalances[edge.key.chanID] < amt {
			return 0
		}

		return maxProbability
	}

	retry := lowerRetryFactor(
		amt, r.sessionFailedAt[edge.key],
	)
	if retry == 0 {
		return 0
	}

	probability := beliefProbability(edge, amt)
	belief := beliefSnapshot(edge)
	if r.sessionFailedAt[edge.key] != 0 &&
		belief.lowerOK < amt {

		probability *= retry
	}

	return clampProbability(probability)
}

type pathLabel struct {
	node    route.Vertex
	amount  lnwire.MilliSatoshi
	score   float64
	logRisk float64
	hops    int

	edge   *candidateEdge
	next   *pathLabel
	active bool
}

type pathQueue []*pathLabel

func (q pathQueue) Len() int {
	return len(q)
}

func (q pathQueue) Less(i, j int) bool {
	if math.Abs(q[i].score-q[j].score) > 1e-12 {
		return q[i].score < q[j].score
	}
	if q[i].hops != q[j].hops {
		return q[i].hops < q[j].hops
	}

	return q[i].amount < q[j].amount
}

func (q pathQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *pathQueue) Push(value any) {
	*q = append(*q, value.(*pathLabel))
}

func (q *pathQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func labelContains(
	label *pathLabel,
	node route.Vertex) bool {

	for current := label; current != nil; current = current.next {
		if current.node == node {
			return true
		}
	}

	return false
}

func labelRank(
	label *pathLabel,
	deliver lnwire.MilliSatoshi) float64 {

	ratio := float64(label.amount) /
		math.Max(float64(deliver), 1)

	return label.score +
		0.025*float64(label.hops) +
		0.08*math.Log(math.Max(ratio, 1))
}

func insertLabel(
	labels map[route.Vertex][]*pathLabel,
	label *pathLabel,
	deliver lnwire.MilliSatoshi) bool {

	current := labels[label.node]
	kept := current[:0]

	for _, existing := range current {
		if !existing.active {
			continue
		}

		existingDominates := existing.amount <= label.amount &&
			existing.score <= label.score &&
			existing.hops <= label.hops
		if existingDominates {
			return false
		}

		labelDominates := label.amount <= existing.amount &&
			label.score <= existing.score &&
			label.hops <= existing.hops
		if labelDominates {
			existing.active = false
			continue
		}

		kept = append(kept, existing)
	}

	label.active = true
	kept = append(kept, label)

	if len(kept) > maxNodeLabels {
		worst := 0
		worstRank := labelRank(kept[0], deliver)

		for i := 1; i < len(kept); i++ {
			rank := labelRank(kept[i], deliver)
			if rank > worstRank {
				worst = i
				worstRank = rank
			}
		}

		if kept[worst] == label {
			return false
		}

		kept[worst].active = false
		kept = append(kept[:worst], kept[worst+1:]...)
	}

	labels[label.node] = kept
	return label.active
}

func (r *candidateRouter) findRoute(
	deliver lnwire.MilliSatoshi) (*route.Route, float64, float64, error) {

	if deliver <= 0 {
		return nil, 0, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, 0, errors.New("source equals target")
	}

	root := &pathLabel{
		node:   r.spec.Target,
		active: true,
		amount: deliver,
	}
	labels := map[route.Vertex][]*pathLabel{
		r.spec.Target: {root},
	}
	queue := &pathQueue{}
	heap.Push(queue, root)

	for queue.Len() != 0 {
		label := heap.Pop(queue).(*pathLabel)
		if !label.active {
			continue
		}

		if label.node == r.source {
			rt, err := r.buildRoute(deliver, label)
			if err != nil {
				return nil, 0, 0, err
			}

			return rt, label.logRisk, label.score, nil
		}

		if label.hops >= maxRouteHops {
			continue
		}

		for _, edge := range r.incomingEdges[label.node] {
			if labelContains(label, edge.key.from) {
				continue
			}

			amountOver := label.amount
			if edge.key.from == r.source {
				if amountOver <= 0 ||
					amountOver > edge.capacity {

					continue
				}
			} else if !edge.usable(amountOver) {
				continue
			}

			probability := r.edgeProbability(edge, amountOver)
			if probability <= 0 {
				continue
			}

			sending := amountOver
			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOver)
				if fee < 0 || sending > math.MaxInt64-fee {
					continue
				}
				sending += fee
			}

			edgeRisk := -math.Log(probability)
			feePenalty := 5 * float64(fee) /
				math.Max(float64(deliver), 1)
			hopPenalty := 0.04 +
				0.0025*float64(label.hops)

			utilization := float64(amountOver) /
				math.Max(float64(edge.capacity), 1)
			capacityPenalty := 0.0
			if utilization > 0.70 {
				excess := (utilization - 0.70) / 0.30
				capacityPenalty = 0.30 * excess * excess
			}

			nextLabel := &pathLabel{
				node:    edge.key.from,
				amount:  sending,
				score: label.score + edgeRisk +
					r.sessionPenalty[edge.key] +
					feePenalty + hopPenalty +
					capacityPenalty,
				logRisk: label.logRisk + edgeRisk,
				hops:    label.hops + 1,
				edge:    edge,
				next:    label,
			}

			if !insertLabel(labels, nextLabel, deliver) {
				continue
			}

			heap.Push(queue, nextLabel)
		}
	}

	return nil, 0, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(
	deliver lnwire.MilliSatoshi,
	sourceLabel *pathLabel) (*route.Route, error) {

	path := make([]*candidateEdge, 0, sourceLabel.hops)
	for current := sourceLabel; current != nil &&
		current.edge != nil; current = current.next {

		path = append(path, current.edge)
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = deliver
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		fee := outgoing.fee(amounts[i+1])
		if fee < 0 || amounts[i+1] > math.MaxInt64-fee {
			return nil, errors.New("route amount overflow")
		}

		amounts[i] = amounts[i+1] + fee
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmount := deliver
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			forwardAmount = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmount,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func ceilDivide(
	amount lnwire.MilliSatoshi,
	divisor uint32) lnwire.MilliSatoshi {

	if divisor <= 1 {
		return amount
	}

	d := lnwire.MilliSatoshi(divisor)
	result := amount / d
	if amount%d != 0 {
		result++
	}

	return result
}

func (r *candidateRouter) shardAmounts(
	amt lnwire.MilliSatoshi,
	partsLeft uint32) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{amt}
	}

	minimum := ceilDivide(amt, partsLeft)
	seen := make(map[lnwire.MilliSatoshi]bool)
	amounts := make([]lnwire.MilliSatoshi, 0, 36)

	add := func(shard lnwire.MilliSatoshi) {
		if shard < minimum || shard > amt || shard <= 0 {
			return
		}
		if seen[shard] || len(amounts) >= 36 {
			return
		}

		seen[shard] = true
		amounts = append(amounts, shard)
	}

	add(amt)
	add(minimum)

	limit := partsLeft
	if limit > 20 {
		limit = 20
	}
	for parts := uint32(2); parts <= limit; parts++ {
		add(ceilDivide(amt, parts))
	}

	for _, fraction := range [][2]int64{
		{7, 8}, {3, 4}, {2, 3}, {3, 5}, {1, 2},
		{2, 5}, {1, 3},
	} {
		numerator := lnwire.MilliSatoshi(fraction[0])
		denominator := lnwire.MilliSatoshi(fraction[1])
		value := (amt/denominator)*numerator +
			(amt%denominator)*numerator/denominator
		add(value)
	}

	failedAmounts := make([]lnwire.MilliSatoshi, 0,
		len(r.sessionFailedAt))
	for _, failedAt := range r.sessionFailedAt {
		if failedAt > 1 {
			failedAmounts = append(failedAmounts, failedAt)
		}
	}
	sort.Slice(failedAmounts, func(i, j int) bool {
		return failedAmounts[i] > failedAmounts[j]
	})

	for _, failedAt := range failedAmounts {
		for _, divisor := range []lnwire.MilliSatoshi{
			2, 4, 8, 16,
		} {
			add((failedAt - 1) / divisor)
		}
	}

	sort.Slice(amounts, func(i, j int) bool {
		return amounts[i] > amounts[j]
	})

	return amounts
}

func (r *candidateRouter) RequestRoute(
	amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount is zero")
	}
	if r.attempts >= attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("no payment parts remaining")
	}

	partsLeft := maxParts - inFlightHtlcs
	minimum := ceilDivide(amt, partsLeft)
	shards := r.shardAmounts(amt, partsLeft)

	progressWeight := 0.68
	switch {
	case r.successfulParts != 0:
		progressWeight = 0.86

	case r.failedAttempts >= 3:
		progressWeight = 0.44

	case r.failedAttempts != 0:
		progressWeight = 0.55
	}

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, shard := range shards {
		rt, risk, searchScore, err := r.findRoute(shard)
		if err != nil {
			continue
		}

		progress := math.Log(
			math.Max(
				float64(shard)/float64(minimum), 1,
			),
		)
		fee := rt.TotalAmount - shard
		feePenalty := 4 * float64(fee) /
			math.Max(float64(shard), 1)
		nonRiskCost := math.Max(searchScore-risk, 0)

		completionBonus := 0.0
		if shard == amt {
			completionBonus = 0.06
		}

		utility := -risk +
			progressWeight*progress +
			completionBonus -
			feePenalty -
			0.25*nonRiskCost

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	return bestRoute, nil
}

func (r *candidateRouter) routeEdges(
	rt *route.Route) ([]*candidateEdge, []lnwire.MilliSatoshi) {

	edges := make([]*candidateEdge, 0, len(rt.Hops))
	amounts := make([]lnwire.MilliSatoshi, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for i, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		edge := r.edgesByKey[key]
		if edge == nil {
			edge = &candidateEdge{
				key: key,
			}
		}

		amount := rt.TotalAmount
		if i > 0 {
			amount = rt.Hops[i-1].AmtToForward
		}

		edges = append(edges, edge)
		amounts = append(amounts, amount)
		from = hop.PubKeyBytes
	}

	return edges, amounts
}

func failureEdgeIndex(
	rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}

	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}

	return -1
}

func (r *candidateRouter) shiftSessionLiquidity(
	edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	failedAt := r.sessionFailedAt[edge.key]
	if failedAt != 0 {
		if failedAt > amt {
			r.sessionFailedAt[edge.key] = failedAt - amt
		} else {
			r.sessionFailedAt[edge.key] = 1
		}
	}

	key := reverseKey(edge.key)
	reverseFailedAt := r.sessionFailedAt[key]
	if reverseFailedAt == 0 {
		return
	}

	if reverseFailedAt > edge.capacity-amt {
		delete(r.sessionFailedAt, key)
	} else {
		r.sessionFailedAt[key] = reverseFailedAt + amt
	}
}

func (r *candidateRouter) ReportAttempt(
	attemptID uint64,
	rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	r.attempts++

	if rt == nil {
		return errors.New("nil attempted route")
	}
	if len(rt.Hops) == 0 {
		return errors.New("attempted route has no hops")
	}

	edges, amounts := r.routeEdges(rt)

	if result.Failure == nil {
		r.successfulParts++

		for i, edge := range edges {
			if edge.capacity == 0 {
				continue
			}

			recordSettlement(edge, amounts[i])
			r.shiftSessionLiquidity(edge, amounts[i])

			if r.sessionPenalty[edge.key] > 0.25 {
				r.sessionPenalty[edge.key] *= 0.12
			} else {
				delete(r.sessionPenalty, edge.key)
			}
		}

		firstChan := rt.Hops[0].ChannelID
		if r.localBalances[firstChan] > rt.TotalAmount {
			r.localBalances[firstChan] -= rt.TotalAmount
		} else {
			r.localBalances[firstChan] = 0
		}

		return nil
	}

	r.failedAttempts++

	failIndex := failureEdgeIndex(
		rt, result.FailureSource,
	)
	if failIndex >= 0 {
		prefixEnd := failIndex
		if prefixEnd > len(edges) {
			prefixEnd = len(edges)
		}

		for i := 0; i < prefixEnd; i++ {
			edge := edges[i]
			if edge.capacity == 0 {
				continue
			}

			recordProbeSuccess(edge, amounts[i])
			if r.sessionPenalty[edge.key] > 0.30 {
				r.sessionPenalty[edge.key] *= 0.25
			} else {
				delete(r.sessionPenalty, edge.key)
			}
		}
	}

	code := result.Failure.Code()
	if failIndex >= 0 && failIndex < len(edges) {
		edge := edges[failIndex]
		if edge.capacity == 0 {
			return nil
		}

		switch code {
		case lnwire.CodeTemporaryChannelFailure:
			amount := amounts[failIndex]
			recordLiquidityFailure(edge, amount)

			previous := r.sessionFailedAt[edge.key]
			if previous == 0 || amount < previous {
				r.sessionFailedAt[edge.key] = amount
			}
			r.sessionPenalty[edge.key] += 1.25

			if edge.key.from == r.source &&
				r.localBalances[edge.key.chanID] >= amount {

				r.localBalances[edge.key.chanID] = amount - 1
			}

		case lnwire.CodeFeeInsufficient,
			lnwire.CodeIncorrectCltvExpiry:

			r.sessionBlocked[edge.key] = true
			r.sessionPenalty[edge.key] += 6

		default:
			r.sessionBlocked[edge.key] = true
			r.sessionPenalty[edge.key] += 3
		}

		return nil
	}

	penalized := 0
	for _, edge := range edges {
		if edge.capacity != 0 &&
			edge.key.from != r.source {

			penalized++
		}
	}
	if penalized == 0 {
		return nil
	}

	increment := 1.5 / math.Sqrt(float64(penalized))
	for _, edge := range edges {
		if edge.capacity == 0 ||
			edge.key.from == r.source {

			continue
		}

		r.sessionPenalty[edge.key] += increment
	}

	return nil
}

func minMSat(
	a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if a < b {
		return a
	}

	return b
}

func (r *candidateRouter) String() string {
	return fmt.Sprintf(
		"candidateRouter(source=%v,target=%v)",
		r.source, r.spec.Target,
	)
}
